data class Chat(val sender: String, val unread: Int)

fun main() {
    val chats = listOf(Chat("Cara", 2), Chat("Abe", 5), Chat("Bob", 2), Chat("Dan", 5))
    val sorted = chats.sortedWith(
        compareByDescending<Chat> { it.unread }.thenBy { it.sender }
    )
    println(sorted.map { it.sender })
}

